insert into public.pages (id, key, title_ar, title_en, body_ar, body_en, status) values
  ('de5eed00-0000-4000-8000-000000000202', 'privacy', 'سياسة الخصوصية (مسودة)', 'Privacy policy (draft)',
    '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "مسودة للمراجعة: هذا نص تجريبي لم يراجعه أحمد بعد (§14 #8). لا يُعمل به ولا يُعدّ نصًا قانونيًا نهائيًا.", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "توضح هذه السياسة البيانات التي نجمعها عند استخدامك الموقع، ولماذا نجمعها، وكم نحتفظ بها، وما حقوقك عليها."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "البيانات التي نجمعها"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "بيانات الحساب: الاسم والبريد الإلكتروني، ورقم الهاتف والجهة والصفة إن أضفتها."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "طلبات الاستشارة ورسائل المحادثة والملفات المرفقة بها."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "طلبات الوثائق، وسجل فتح الوثائق الممنوحة لك (من فتحها ومتى)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "رسائل نموذج التواصل."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "بيانات استخدام عامة للصفحات العامة، فقط إذا قبلت ملفات التحليل."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "لماذا نستخدمها"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "للرد على طلبات الاستشارة ومتابعتها معك."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "لمنحك الوصول إلى الوثائق المحمية، ولحمايتها بالعلامة المائية وسجل الفتح."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "لإرسال إشعارات تتعلق بطلباتك."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "لتحسين الموقع من بيانات استخدام مجمّعة لا تتضمن نص رسائلك."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "مدة الاحتفاظ بالبيانات"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "نحتفظ ببياناتك إلى أن يحذفها أحد مسؤولي الموقع. يمكنك طلب الحذف في أي وقت عبر صفحة التواصل."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "حقوقك"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "الاطلاع على بياناتك المحفوظة لدينا."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "تصحيح بياناتك من صفحة حسابك أو بطلب منا."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "طلب حذف حسابك وبياناتك."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "سحب موافقتك على ملفات التحليل في أي وقت."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "الموافقة"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "عند إنشاء الحساب تُطلب منك الموافقة الصريحة على سياسة الخصوصية وشروط الاستخدام، ونحفظ وقت موافقتك."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ملفات تعريف الارتباط"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "نستخدم أداة التحليل PostHog، لذلك يظهر لك شريط للموافقة على ملفات تعريف الارتباط. إذا رفضت، تعمل الأداة دون أي ملفات تعريف ارتباط. ملفات تسجيل الدخول اللازمة لعمل الحساب تبقى في الحالتين."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "التواصل"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لأي سؤال عن هذه السياسة أو عن بياناتك، راسلنا من صفحة التواصل."}]}]}'::jsonb,
    '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Draft for review: placeholder text, not yet reviewed by Ahmed (§14 #8). It is not in force and is not final legal text.", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This policy explains what data we collect when you use the site, why, how long we keep it, and your rights over it."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data we collect"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Account details: your name and email, and your phone, organization and role if you add them."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Consultation requests, chat messages and the files attached to them."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Document requests, and the log of when documents granted to you were opened, and by whom."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Messages sent through the contact form."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "General usage data on public pages, only if you accept analytics cookies."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why we use it"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "To answer your consultation requests and follow up with you."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "To give you access to protected documents, and to protect them with a watermark and an open log."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "To send you notifications about your requests."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "To improve the site, using aggregate usage data that never includes your message text."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How long we keep it"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We keep your data until a site admin deletes it. You can ask for deletion at any time through the contact page."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Your rights"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "See the data we hold about you."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Correct it from your account page, or by asking us."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask us to delete your account and your data."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Withdraw your consent to analytics cookies at any time."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Consent"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When you create an account, you are asked to accept this privacy policy and the terms of use explicitly. We store the time you accepted."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Cookies"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We use PostHog for analytics, so the site shows a cookie banner. If you decline, PostHog runs without any cookies. The sign-in cookies your account needs are used either way."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Contact"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "For any question about this policy or your data, write to us from the contact page."}]}]}'::jsonb,
    'published'),
  ('de5eed00-0000-4000-8000-000000000203', 'terms', 'شروط الاستخدام (مسودة)', 'Terms of use (draft)',
    '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "مسودة للمراجعة: هذا نص تجريبي لم يراجعه أحمد بعد (§14 #8). لا يُعمل به ولا يُعدّ نصًا قانونيًا نهائيًا.", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "باستخدامك هذا الموقع أو إنشاء حساب فيه، فإنك توافق على الشروط التالية."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "طبيعة الاستشارات"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "الاستشارات المقدمة عبر الموقع رأي مهني في الإدارة والحوكمة والعمل الإنساني والتنمية، مبني على المعلومات التي تقدمها. القرار النهائي ومسؤولية تنفيذه يعودان إليك."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "سرية المحادثات"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "محادثات الاستشارة خاصة بينك وبين فريق الموقع، ولا تُنشر ولا تُشارك مع أي طرف آخر. يلتزم الفريق بسريتها، ونرجو ألا تشارك بيانات دخول حسابك مع أحد."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "الوثائق الممنوحة"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "الوثائق المحمية تُمنح لك للاطلاع الشخصي فقط."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "لا يجوز مشاركتها أو نسخها أو إعادة نشرها بأي شكل."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "كل وثيقة تحمل علامة مائية باسمك، ويُسجَّل كل فتح لها."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "يحق للمسؤول سحب الوصول إلى أي وثيقة في أي وقت."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "الاتفاقات المالية"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "لا يجري الموقع أي عملية دفع. أي اتفاق مالي على الخدمات يتم خارج الموقع مباشرة بينك وبين أحمد."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "الحساب"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "أنت مسؤول عن صحة البيانات التي تقدمها وعن استخدام حسابك. تُطلب موافقتك الصريحة على هذه الشروط عند إنشاء الحساب."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "تعديل الشروط"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "قد نعدّل هذه الشروط، وننشر النسخة المعدّلة على هذه الصفحة."}]}]}'::jsonb,
    '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Draft for review: placeholder text, not yet reviewed by Ahmed (§14 #8). It is not in force and is not final legal text.", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "By using this site or creating an account on it, you agree to the terms below."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Nature of consultations"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Consultations given through the site are a professional opinion on management, governance, humanitarian work and development, based on the information you provide. The final decision, and responsibility for acting on it, stay with you."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Confidentiality of chats"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Consultation chats are private between you and the site''s team. They are never published or shared with anyone else. The team keeps them confidential; please don''t share your sign-in details with anyone."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Granted documents"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Protected documents are granted to you for your own viewing only."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You may not share, copy or republish them in any form."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Every document carries a watermark with your name, and every open is logged."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The admin may withdraw access to any document at any time."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Financial agreements"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The site takes no payments. Any financial agreement for services happens outside the site, directly between you and Ahmed."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Your account"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You are responsible for the accuracy of the details you give and for the use of your account. You are asked to accept these terms explicitly when you create it."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Changes to these terms"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We may change these terms, and we publish the changed version on this page."}]}]}'::jsonb,
